const body = $input.first().json.body || $input.first().json;
const branche = body.branche || 'Allgemein';
const firmenname = body.firmenname || body.name || 'Ihr Betrieb';
const ort = body.ort || 'Berlin';
const email = body.email || '';
const beschreibung = body.beschreibung || '';

const profiles = {
  'Maler': { c: 'Dunkelblau, Terrakotta, Creme', s: 'Hero, Leistungen, Galerie, Kontakt, Footer', m: 'Warm', e: 'Gradient-Boxen' },
  'Elektriker': { c: 'Dunkelblau, Amber, Cremeweiß', s: 'Hero, Leistungen, Notdienst, Kontakt, Footer', m: 'Technisch', e: 'Notdienst-Box' },
  'default': { c: 'Dunkelblau, Gold, Creme', s: 'Hero, Leistungen, Kontakt, Footer', m: 'Professionell', e: 'USP-Karten' }
};
const p = profiles[branche] || profiles['default'];

const prompt = `Erstelle eine professionelle Microsite fuer:\nFirma: ${firmenname}\nBranche: ${branche}\nStadt: ${ort}\nE-Mail: ${email || 'Auf Anfrage'}\nBeschreibung: ${beschreibung || 'Standardleistungen'}\n\nDesign: ${p.c}, ${p.s}, ${p.m}, ${p.e}\n\nRegeln:\n1. Nur HTML (<!DOCTYPE html> bis </html>)\n2. Inline CSS im head\n3. Mobil-optimiert mit viewport meta\n4. Google Fonts Inter\n5. tel: und mailto: Links\n6. Footer: © 2026 ${firmenname}. Demo-Website erstellt von Werkspree\n7. Responsive bei 768px und 480px\n8. CSS-Animationen\n\nBeginne mit <!DOCTYPE html>.`;

const apiKey = $env.GOOGLE_API_KEY;
if (!apiKey) {
  return [{json: {html: '<html><body><h1>Generator nicht verfuegbar</h1></body></html>', success: false}}];
}

const geminiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash-exp:generateContent?key=${apiKey}`;

try {
  const resp = await fetch(geminiUrl, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      contents: [{parts: [{text: prompt}]}],
      generationConfig: {temperature: 0.4, maxOutputTokens: 8000}
    })
  });
  const data = await resp.json();
  let html = '';
  if (data.candidates && data.candidates[0]) {
    html = data.candidates[0].content.parts[0].text || '';
  }
  const match = html.match(/<![Dd][Oo][Cc][Tt][Yy][Pp][Ee][^>]*>[\\s\\S]*?<\\/[Hh][Tt][Mm][Ll]>/);
  if (match) html = match[0];
  const wm = '<div style="position:fixed;bottom:10px;right:10px;background:rgba(31,157,116,0.9);color:#fff;padding:5px 15px;border-radius:999px;font-size:0.8rem;font-weight:600;z-index:99999">Demo von Werkspree</div>';
  if (html.includes('</body>')) html = html.replace('</body>', wm + '</body>'); else html += wm;
  return [{json: {html: html, success: true}}];
} catch(e) {
  return [{json: {html: '<html><body><h1>Fehler</h1></body></html>', success: false}}];
}
